    ('"Music To Your Eyes"', 'Bill Pope''s new photography show: portraits of musicians and their instruments, revealing the emotion and energy they and their music convey, taken over the past 20 years, mostly on Gabriola Island', '2026-09-11'::date, '2026-10-29'::date, '09:00:00'::time, '17:00:00'::time, false, 'Gabriola Medical Clinic', 'Gabriola Medical Clinic', '695 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/music-to-your-eyes-1909490', false),
  ('Grocery Program (Food Bank) at PHC', 'The only requirements on your first visit typically involve filling out an intake form. Expect to provide ID and proof of address. You will be asked for personal information, which will be kept confidential, such as your income and expenses as well as how many people are in your household. No one is turned away. For any additional questions please contact 250-247-7322 or food@phcgabriola.org or by dropping in during grocery hours', '2026-09-15'::date, '2026-12-22'::date, NULL::time, NULL::time, true, 'People for a Healthy Community on Gabriola Society', 'People for a Healthy Community on Gabriola Society', '675 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/grocery-program-food-bank-at-phc-1768213', false),
  ('30th Annual Thanksgiving Studio Tour', 'Celebrate 30 years of creativity at the Annual Thanksgiving Studio Tour on Gabriola Island. This beloved self-guided event invites visitors to explore artists’ studios across the island, meet the creators, and experience a rich variety of visual art, craft, and design—all set against the beauty of Gabriola in the fall', '2026-10-10'::date, '2026-10-12'::date, '10:00:00'::time, '17:00:00'::time, false, 'Gabriola Island', NULL, NULL, 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/30th-annual-thanksgiving-studio-tour-1622575', true),
