  ('Open Mic Night at the Gabriola Golf Club', 'Local artists from 6pm till 10pm on Mondays at the Gabriola Golf Club, 825 South Rd', '2026-10-12'::date, '2026-10-12'::date, '18:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/open-mic-night-at-the-gabriola-golf-club-1887552', true),
  ('Duplicate Bridge at the Rollo Centre', 'The Duplicate Bridge group meets every Monday evening at 6:30pm for 3 hours of brain gymnastics in a convivial atmosphere. Currently we average 3 tables/evening (12 players), and we are actively recruiting more players. Although we are no longer sanctioned by the ACBL, scores are always tallied and the top pair always enjoys ***FREE PLAY*** for their next session. An activity fee of $4.00 is charged ($2 for Rollo; $2 for cookies). Coffee, tea, and cookies are always served!', '2026-10-12'::date, '2026-10-12'::date, '18:30:00'::time, '21:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/duplicate-bridge-at-the-rollo-centre-1884638', true),
  ('The Palette People at the Rollo Centre', 'Meet to draw, paint, inspire and support each other every Tuesday and Friday from 9:30am to noon, and often into the afternoon at the Rollo Centre. For more information, visit our website: About Gabriola Palette People', '2026-10-13'::date, '2026-10-13'::date, '09:30:00'::time, '12:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/the-palette-people-at-the-rollo-centre-1895484', true),
  ('Soup Social (PHC)', 'Soup Socials provide delicious and nutritional meals in a casual setting. This is an event within the community to share a meal which fosters social connection and strengthens relationships. Join us and see what interesting conversation you can engage in with your fellow neighbors. Drop-in, all ages. Dates: Tuesdays, 11am-1pm. Location: Summer: Commons (main floor), 675 North Rd. Winter: Fellowship Church, 775 Church St (approx second week of Oct). Cost: FREE or by donation', '2026-10-13'::date, '2026-10-13'::date, '11:00:00'::time, '13:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/soup-social-phc-1884337', true),
  ('Yoga for All (Tue 11:30am)', 'Gabriola Recreation Society program (26FA-YA1130). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-10-13'::date, '2026-10-13'::date, '11:30:00'::time, '12:30:00'::time, false, 'Gabriola Recreation Society space', 'Gabriola Recreation Society space', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('Chair Yoga at Gabriola Library', 'We are offering Chair Yoga at the library! Certified yoga instructor Nora will lead a weekly series of classes every Tuesday from 1:00 to 2:00 starting September 8 thru to October 13. No need to register - drop in and try it out!', '2026-10-13'::date, '2026-10-13'::date, '13:00:00'::time, '14:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/chair-yoga-at-gabriola-library-1917837', true),
