  ('Lego Club at the Gabriola Library', 'Tuesdays at the Gabriola Library from 3pm-5pm. Drop in to the meeting room and use our mountains of Lego to let your imagination fly! Challenge cards will inspire your creations. Open to all ages', '2026-10-13'::date, '2026-10-13'::date, '15:00:00'::time, '17:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/lego-club-at-the-gabriola-library-1895582', true),
