  ('Chair Yoga (Wed 3pm)', 'Gabriola Recreation Society program (26FA-CY3). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-10-14'::date, '2026-10-14'::date, '15:00:00'::time, '16:00:00'::time, false, 'Gabriola Recreation Society space', 'Gabriola Recreation Society space', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('Tech-Help Wednesdays at the Gabriola Library', 'Wednesdays from 3pm-5pm at the Gabriola Library. Let us help you figure out your device issues. Whether it''s your laptop, tablet, eReader, or phone - we will do what we can to reduce your frustrations!Please bring your device, library card, and any passwords you may need. to book your free, 30-minute tech appointment', '2026-10-14'::date, '2026-10-14'::date, '15:00:00'::time, '17:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/tech-help-wednesdays-at-the-gabriola-library-1895899', true),
