  ('The Palette People at the Rollo Centre', 'Meet to draw, paint, inspire and support each other every Tuesday and Friday from 9:30am to noon, and often into the afternoon at the Rollo Centre. For more information, visit our website: About Gabriola Palette People', '2026-10-16'::date, '2026-10-16'::date, '09:30:00'::time, '12:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/the-palette-people-at-the-rollo-centre-1895485', true),
  ('Coffee & Lunch Social at the Christ Church', 'Every Friday from 10:30am to 12:30pm at Christ Church Gabriola. This is a great time for our community to get together. The soup and desserts are always amazing and each week we have musicians to entertain us. A non-religious event. Also supported by PHC', '2026-10-16'::date, '2026-10-16'::date, '10:30:00'::time, '12:30:00'::time, false, 'Christ Church', 'Christ Church', '2600 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/coffee-lunch-social-at-the-christ-church-1903249', true),
  ('AA Meeting at Gabriola Fellowship Church', 'AA Group meets downstairs weekly at the Gabriola Fellowship Church on the following days and times: Sundays at 7:00 pm Wednesdays at 7:00 pm Fridays at 12:00 pm', '2026-10-16'::date, '2026-10-16'::date, '12:00:00'::time, '13:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/aa-meeting-at-gabriola-fellowship-church-1895816', true),
