  ('Weller Gabriola Talks', 'Listed on the Rollo Centre calendar (a room booking calendar). Times shown are the booking and may include setup. Check with the organizer for event hours.', '2026-10-17'::date, '2026-10-17'::date, '18:00:00'::time, '20:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Rollo Centre calendar', 'https://www.gabriolaseniorscentre.com/activities', false),
  ('2026 General Local Election', 'The next general local elections are Saturday, October 17th, 2026, with advanced voting periods on Wednesday, October 7th, and Wednesday, October 14th. Voters will elect 26 trustees across the Islands Trust Area. Elected officials serve a four-year term from November 2026 to October 2030.You may vote for an Electoral Area Director (Area B - Gabriola), School District Trustee Candidates (School District 68 - Gabriola), Gabriola Island Local Trust Committee Trustees, and any applicable assent voting (referendum) questions. For more information, visit 2026 General Local Elections | RDN and Elections — About Us — Islands Trust', '2026-10-17'::date, '2026-10-17'::date, NULL::time, NULL::time, true, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/2026-general-local-election-1900326', true),
