  ('Little Songbirds (Infants to age 4)', 'Gabriola Recreation Society program (26FA-LS). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-10-21'::date, '2026-10-21'::date, '10:00:00'::time, '11:00:00'::time, false, 'Gabriola Recreation Society space', 'Gabriola Recreation Society space', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('Shut Up & Write! at the Gabriola Library', 'A 2-hour session of silent writing on Wednesdays at the Gabriola Library. No discussions, just quick introductions then work silently on your writing project. 10am-12pm. Optional discussion period from 12pm-12:30pm', '2026-10-21'::date, '2026-10-21'::date, '10:00:00'::time, '12:30:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/shut-up-write-at-the-gabriola-library-1886996', true),
  ('Mom''s Group at the Gabriola Fellowship Church', 'Mom''s Group meeting every Wednesday at the Gabriola Fellowship Church from 10:30am - 1:30pm. We host a supportive and welcoming space for moms to connect, share experiences, and build lasting friendships. Whether you''re a new mom or seasoned pro, come join us for encouragement, laughter, and real talk about motherhood', '2026-10-21'::date, '2026-10-21'::date, '10:30:00'::time, '13:30:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/mom-s-group-at-the-gabriola-fellowship-church-1901038', true),
  ('PHC Speaker Series', 'Listed on the Rollo Centre calendar (a room booking calendar). Times shown are the booking and may include setup. Check with the organizer for event hours.', '2026-10-21'::date, '2026-10-21'::date, '12:30:00'::time, '15:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Rollo Centre calendar', 'https://www.gabriolaseniorscentre.com/activities', false),
  ('Literacy Central Vancouver Island (LCVI) Digital Workshops for Seniors', 'Literacy Central Vancouver Island (LCVI) is happy to provide PCH with opportunities to explore topics on digital literacy, designed to keep you safe and secure in the digital era, while gaining an understanding of how technology is rapidly evolving. We invite you to join the following session:Artificial Intelligence (AI): Risks, Benefits, and Opportunities - October 21, 2026 - 1:00pm - 3:00pm You''ve likely heard of the fast rise of Artificial Intelligence or "AI". This session is designed to help you gain a more robust understanding of AI and how it is used in daily life for individuals, researchers, and corporations. This session will help you understand what AI is and where it appears in daily life; explore practical ways to use AI tools; be able to spot fake images/videos, scam calls, and misleading AI content; and verify information to stay informed and safe online. A portion of the session will help you also understand how AI may also help humanity while gaining an understanding for its potential for the future. These sessions will be delivered by Anne-Marie E. Fischer of LCVI, along with one of their dedicated volunteers. The sessions will be interactive and have the intentio', '2026-10-21'::date, '2026-10-21'::date, '13:00:00'::time, '15:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/literacy-central-vancouver-island-lcvi-digital-workshops-for-seniors-1940537', true),
  ('Meet for Meditation at the Gabriola Library', 'Meet for meditation on Wednesdays at the Gabriola Library from 1pm-2pm. Art of Living teacher, Susan Murray, will lead you through a wonderfully relaxing session no matter your experience level. No registration required', '2026-10-21'::date, '2026-10-21'::date, '13:00:00'::time, '14:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/meet-for-meditation-at-the-gabriola-library-1887042', true),
  ('Tech-Help Wednesdays at the Gabriola Library', 'Wednesdays from 3pm-5pm at the Gabriola Library. Let us help you figure out your device issues. Whether it''s your laptop, tablet, eReader, or phone - we will do what we can to reduce your frustrations!Please bring your device, library card, and any passwords you may need. to book your free, 30-minute tech appointment', '2026-10-21'::date, '2026-10-21'::date, '15:00:00'::time, '17:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/tech-help-wednesdays-at-the-gabriola-library-1895900', true),
  ('Youth Group at the Gabriola Fellowship Church', 'Youth group on Wednesdays from 4:30pm to 6:30pm at the Gabriola Fellowship Church', '2026-10-21'::date, '2026-10-21'::date, '16:30:00'::time, '18:30:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/youth-group-at-the-gabriola-fellowship-church-1903078', true),
  ('Games Night at the Gabriola Golf Club', 'Games night at the Gabriola Golf Club on Wednesdays from 6pm-10pm. Poker, cards, board games with expanded menu', '2026-10-21'::date, '2026-10-21'::date, '18:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/games-night-at-the-gabriola-golf-club-1886031', true),
  ('Drop-in Indoor Soccer', 'Gabriola Recreation Society program (26FA-SDI). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-10-21'::date, '2026-10-21'::date, '18:30:00'::time, '20:00:00'::time, false, 'Gabriola Elementary School', 'Gabriola Elementary School', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('Chess at the Rollo Centre', 'Everyone is welcome to drop in for a game of chess on Wednesdays from 7-9pm. We have a regular turnout of roughly 8-10 players (and growing). All ages and levels are welcome. Bring your own board if you like, but we have plenty of the club-style sets available. A $2 activity for Rollo members, $5 drop-in fee for non-members. Play is informal and tea and cookies are provided', '2026-10-21'::date, '2026-10-21'::date, '19:00:00'::time, '21:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/chess-at-the-rollo-centre-1880461', true),
  ('Tea Thursdays at the Gabriola Library', 'Enjoy a cup of tea (or spa water on hot days!) all day on Thursdays (10am-7pm), thanks to the Friends of the Gabriola Library', '2026-10-22'::date, '2026-10-22'::date, '10:00:00'::time, '19:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/tea-thursdays-at-the-gabriola-library-1886859', true),
  ('Seniors Monthly Luncheon at the Rollo Centre', 'Fourth Thursday of every month, 10:30 AM - 12:30 PM at the Rollo Seniors Centre. Drop-in or register online at phcgabriola.org. Luncheon to connect with friends in the community. Local entertainment, guest speakers, and seasonally themed events. Cost: Free (by donation)', '2026-10-22'::date, '2026-10-22'::date, '10:30:00'::time, '12:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/seniors-monthly-luncheon-at-the-rollo-centre-1883844', true),
  ('French Conversation Group at the Gabriola Library', 'Come speak French with us on Thursdays at the Gabriola Library from 1pm-2pm. No preparation is necessary. All levels are welcome. We talk about anything and everything. Venez parler français avec nous le jeudi, de 13 h à 14 h. Aucune préparation nécessaire. Tous les niveaux sont bienvenus. On parle de tout et de rien', '2026-10-22'::date, '2026-10-22'::date, '13:00:00'::time, '14:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/french-conversation-group-at-the-gabriola-library-1887142', true),
  ('Gabriola Basketry Group at the Rollo Centre', 'We are an enthusiastic group of artisans who meet every second Thursday at 1:00pm-4:00pm in the small room at the Rollo Centre for an afternoon of basketry. You can check out the Rollo Activity Calendar online or email Marylyn to find out when the next meeting is. The group started meeting and creating in 2002 on Gabriola. Currently we have eight members on Gabriola and about the same number in Nanaimo. Three of our original group are still actively involved in basket making after 23 years!Over the past few years we have jointly facilitated basketry workshops which helps to increase our member numbers. There are no workshops planned at this time. Contact us for information on any future workshops and feel free to drop-in on our regular activity day to check out the group!', '2026-10-22'::date, '2026-10-22'::date, '13:00:00'::time, '16:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/gabriola-basketry-group-at-the-rollo-centre-1896159', true),
  ('Contract Bridge at the Rollo Centre', 'We meet every Thursday afternoon at 1:30pm. There are anywhere from two to five tables (eight to twenty individuals) who play. Lately there have been four tables. A trophy for the highest score overall is given out. Cash prizes are given out for first and second place plus random cash prizes for card sequences. We enjoy a Christmas potluck lunch and party in December', '2026-10-22'::date, '2026-10-22'::date, '13:30:00'::time, '16:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/contract-bridge-at-the-rollo-centre-1885242', true),
  ('Fit for Life After 50', 'Gabriola Recreation Society program (26FA-FFL). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-10-22'::date, '2026-10-22'::date, '13:30:00'::time, '14:30:00'::time, false, 'Gabriola Recreation Society space', 'Gabriola Recreation Society space', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('Ladies Badminton @ The Community Hall', '2pm-4pm. all levels welcome. Join us for fun, casual badminton games open to all skill levels. No registration or partner required, just drop in, meet new people, and enjoy the game!', '2026-10-22'::date, '2026-10-22'::date, '14:00:00'::time, '16:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/ladies-badminton-the-community-hall-1460260', true),
  ('Spanish Conversation Group at the Gabriola Library', 'Drop in and practice your Spanish with the delightful Fernanda (Spanish is her first language), on Thursdays at the Gabriola Library from 3:30pm-4:30pm. Everyone is welcome!', '2026-10-22'::date, '2026-10-22'::date, '15:30:00'::time, '16:30:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/spanish-conversation-group-at-the-gabriola-library-1887221', true),
  ('Drumming at the Gabriola Arts Centre', '6pm - 7:30pm: Simple Rhythms - no experience needed.7:30pm - 9pm: Intermediate African Ensemble SongsEveryone is welcome, no charge, and some hand drums/balafons are provided. Located at the Gabriola Arts Centre', '2026-10-22'::date, '2026-10-22'::date, '18:00:00'::time, '21:00:00'::time, false, 'Gabriola Arts Council', 'Gabriola Arts Council', '476 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/drumming-at-the-gabriola-arts-centre-1884687', true),
  ('Narcotics Anonymous Meeting at the Gabriola Fellowship Church', 'Narcotics Anonymous meeting at the Gabriola Fellowship Church on Monday and Thursday evenings from 6:00pm - 7:00pm', '2026-10-22'::date, '2026-10-22'::date, '18:00:00'::time, '19:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/narcotics-anonymous-meeting-at-the-gabriola-fellowship-church-1900689', true),
  ('Drop-in Volleyball', 'Gabriola Recreation Society program (26FA-VDI). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-10-22'::date, '2026-10-22'::date, '18:30:00'::time, '20:30:00'::time, false, 'Gabriola Elementary School', 'Gabriola Elementary School', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('Al-Anon Zoom Meeting', 'Al-Anon Zoom meeting through the Gabriola Fellowship Church on Thursday evenings from 7pm - 8pm', '2026-10-22'::date, '2026-10-22'::date, '19:00:00'::time, '20:00:00'::time, false, 'ZOOM', 'ZOOM', NULL, 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/al-anon-zoom-meeting-1901182', true),
  ('"From Gabriola, Bob Bossin, From England, Daniel Cainer"', 'Daniel Cainer, the multi-award-winning, internationally acclaimed, British songwriter and musical storyteller is linking up with Gabriola BC’s legendary “old folksinger”, Bob Bossin for performances around the Salish Sea between October 18 and 25. (See list below.)Daniel Cainer, perennial “Pick of the Edinburgh Fringe”, comes to BC from a seventh run at New York’s prestigious Soho Playhouse. American women’s-music icon, Christine Lavin calls Cainer “the best songwriter in the English-speaking world.” Says the L.A. Times, “Cainer makes you laugh, brings you to tears, and warms your heart.”Bob Bossin founded the legendary Canadian folk group Stringband. He authored the prize-winning book Davy the Punk; he performed the musical medicine show, Bossin''s Home Remedy for Nuclear War and recorded such classic Canadian folk songs as The Maple Leaf Dog, Tugboats, Dief will Be the Chief Again, and Show Us the Length. Now 80, Bossin comes out of retirement to join Cainer. “I couldn’t resist the chance to share a stage with one of my idols,” he says. Hear Cainer’s and Bossin’s songs and find out more about their Salish Sea tour at www.bossin-cainer.com', '2026-10-22'::date, '2026-10-23'::date, '19:30:00'::time, '19:30:00'::time, false, 'Gabriola Agricultural Co-op', 'Gabriola Agricultural Co-op', '465 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/from-gabriola-bob-bossin-from-england-daniel-cainer-1934473', true),
  ('The Palette People at the Rollo Centre', 'Meet to draw, paint, inspire and support each other every Tuesday and Friday from 9:30am to noon, and often into the afternoon at the Rollo Centre. For more information, visit our website: About Gabriola Palette People', '2026-10-23'::date, '2026-10-23'::date, '09:30:00'::time, '12:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/the-palette-people-at-the-rollo-centre-1895487', true),
  ('Coffee & Lunch Social at the Christ Church', 'Every Friday from 10:30am to 12:30pm at Christ Church Gabriola. This is a great time for our community to get together. The soup and desserts are always amazing and each week we have musicians to entertain us. A non-religious event. Also supported by PHC', '2026-10-23'::date, '2026-10-23'::date, '10:30:00'::time, '12:30:00'::time, false, 'Christ Church', 'Christ Church', '2600 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/coffee-lunch-social-at-the-christ-church-1903250', true),
  ('Adult Day Program (PHC)', 'Provides engaging therapeutic activities for individuals experiencing physical, cognitive or social challenges in a safe, supervised environment. Our person-centered programs are developed to offer an opportunity for participants to connect with each other, while also offering respite for caregivers. Dates: Mondays and Fridays, 11:30am-2:30pm. Location: Rollo Seniors Centre, 685 North Rd. Age: 60+ (flexible). Cost: FREE or by donation. Registration required. Participants must complete an Island Health intake assessment. For any questions, please contact seniorsmanager@phcgabriola.org', '2026-10-23'::date, '2026-10-23'::date, '11:30:00'::time, '14:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/adult-day-program-phc-1884584', true),
  ('AA Meeting at Gabriola Fellowship Church', 'AA Group meets downstairs weekly at the Gabriola Fellowship Church on the following days and times: Sundays at 7:00 pm Wednesdays at 7:00 pm Fridays at 12:00 pm', '2026-10-23'::date, '2026-10-23'::date, '12:00:00'::time, '13:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/aa-meeting-at-gabriola-fellowship-church-1895817', true),
  ('Nintendo Switch Time at the Gabriola Library', 'Fridays from 2:30pm-4:45pm at the Gabriola Library. All year round, drop-in and play Nintendo Switch on our giant screen in the meeting room. We have lots of games to choose from or bring your own from home. Best for ages 7+. NO ADULTS PLEASE, for kids only', '2026-10-23'::date, '2026-10-23'::date, '14:30:00'::time, '16:45:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/nintendo-switch-time-at-the-gabriola-library-1896115', true),
  ('Parkinson''s Group at the Rollo Centre', 'We meet Fridays from 2:45pm-4:15pm to share briefly and support each other, and then join in professionally-led exercises designed for people with Parkinson''s Disease and pitched to our level (mostly seated). Care-givers very welcome! Seated Tai Chi every 4th Friday', '2026-10-23'::date, '2026-10-23'::date, '14:45:00'::time, '16:15:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/parkinson-s-group-at-the-rollo-centre-1895967', true),
