  ('Gym Jam (ages 5-6)', 'Gabriola Recreation Society program (26FA-GJ56). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-10-24'::date, '2026-10-24'::date, '11:00:00'::time, '11:45:00'::time, false, 'Gabriola Recreation Society space', 'Gabriola Recreation Society space', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('Gabriola Commons Annual General Meeting', 'IT''S THAT TIME OF YEAR AGAIN! 🌿 Gabriola Commons Annual General Meeting October 25th • 2–4 pm Upstairs at the Commons Farmhouse 🌿 What''s happening at the Commons? 🌿 And where are we going next? COME BE PART OF THE FUTURE OF THE COMMONS Refreshments • Community • Conversation Everyone is welcome 💚', '2026-10-25'::date, '2026-10-25'::date, '14:00:00'::time, '16:00:00'::time, false, 'Gabriola Commons Foundation', 'Gabriola Commons Foundation', '675 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/gabriola-commons-annual-general-meeting-1943854', true),
  ('Dave Robbin’s Sextet', 'More JAZZ coming your way Gabriola. Dave Robbins and his incredible Sextet will be at the Phoenix Auditorium on Sunday, October 25th at 3pm. Dave Robbins-drumsBrad Turner-trumpet multi-Juno Award winner Cory Weeds-alto sax Grammy Award winnerMike Allen-tenor saxMiles Black-pianoSteve Holy-bass Tickets are $40. E-transfer to or cash at Nature Spirit Earth Market. To have a listen: https://youtu.be/2xNFbyp0S-8?si=gG95rnGtszcwtwlw', '2026-10-25'::date, '2026-10-25'::date, '15:00:00'::time, '17:00:00'::time, false, 'Phoenix Auditorium at the Haven', 'Phoenix Auditorium at the Haven', '240 Davis Rd', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/dave-robbin-s-sextet-1943456', true),
  ('Sustainable Gabriola monthly meeting', 'Join us to talk about sustainability issues from a Gabriola perspective. Bring your ideas, find out what’s happening around the community. The meetings are informal, respectful, and open to all', '2026-10-25'::date, '2026-10-25'::date, '15:00:00'::time, '16:30:00'::time, false, 'Gabriola Commons Foundation', 'Gabriola Commons Foundation', '675 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/sustainable-gabriola-monthly-meeting-1920485', true),
  ('AA Meeting at Gabriola Fellowship Church', 'AA Group meets downstairs weekly at the Gabriola Fellowship Church on the following days and times: Sundays at 7:00 pm Wednesdays at 7:00 pm Fridays at 12:00 pm', '2026-10-25'::date, '2026-10-25'::date, '19:00:00'::time, '20:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/aa-meeting-at-gabriola-fellowship-church-1895784', true),
  ('The Palace Band at the Gabriola Golf Course', 'The Palace Band was born from an era of rum smugglers and late night cabaret, when music bubbled with swinging emotion and soul. The raw sounds of old school jazz returns with an energy that will put your feet into motion and a smile on every face, combining soaring vocals with a flash of trumpet and the thunder of drums to make the old time new again. It’s impossible to talk about the creation of The Palace Band without first describing the production that formed them, A Night at the Palace. Every year, for the past 17 years, in the depths of winter, the community of Errington comes together to don their sequins, feathers, flapper dresses and frock coats to put on a completely original night of Vaudeville, Comedy and Burlesque Theatre. While there was always music involved, somewhere around the middle of this dynasty, a solid core band was formed, to be known as The Palace Band. It soon became apparent that performing two sold out weekends a year was not going to be enough to satisfy the appetites of these musical mavericks. Drawing on their collective history of musical theatre, Jazz programs, and a wealth of other musical projects, they created a repertoire inspired by the jazz ', '2026-10-25'::date, '2026-10-25'::date, '19:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/the-palace-band-at-the-gabriola-golf-course-1943859', true),
  ('Line Dancing at the Community Hall', 'Line dancing on Monday evenings from 4pm-6pm at the Gabriola Community Hall', '2026-10-26'::date, '2026-10-26'::date, '16:00:00'::time, '18:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/line-dancing-at-the-community-hall-1887598', true),
  ('Beginner Ukulele Instruction and Singalong', 'Downstairs in the Gabriola Community Hall on Monday evenings from 6pm-8pm. Beginner ukulele: 6-7pm. Sing along and play along: 7-8pm (with a uke or whatever!). Suggested donation = $5', '2026-10-26'::date, '2026-10-26'::date, '18:00:00'::time, '20:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/beginner-ukulele-instruction-and-singalong-1887093', true),
  ('Narcotics Anonymous Meeting at the Gabriola Fellowship Church', 'Narcotics Anonymous meeting at the Gabriola Fellowship Church on Monday and Thursday evenings from 6:00pm - 7:00pm', '2026-10-26'::date, '2026-10-26'::date, '18:00:00'::time, '19:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/narcotics-anonymous-meeting-at-the-gabriola-fellowship-church-1900610', true),
  ('Open Mic Night at the Gabriola Golf Club', 'Local artists from 6pm till 10pm on Mondays at the Gabriola Golf Club, 825 South Rd', '2026-10-26'::date, '2026-10-26'::date, '18:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/open-mic-night-at-the-gabriola-golf-club-1887554', true),
  ('Duplicate Bridge at the Rollo Centre', 'The Duplicate Bridge group meets every Monday evening at 6:30pm for 3 hours of brain gymnastics in a convivial atmosphere. Currently we average 3 tables/evening (12 players), and we are actively recruiting more players. Although we are no longer sanctioned by the ACBL, scores are always tallied and the top pair always enjoys ***FREE PLAY*** for their next session. An activity fee of $4.00 is charged ($2 for Rollo; $2 for cookies). Coffee, tea, and cookies are always served!', '2026-10-26'::date, '2026-10-26'::date, '18:30:00'::time, '21:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/duplicate-bridge-at-the-rollo-centre-1884640', true),
  ('The Palette People at the Rollo Centre', 'Meet to draw, paint, inspire and support each other every Tuesday and Friday from 9:30am to noon, and often into the afternoon at the Rollo Centre. For more information, visit our website: About Gabriola Palette People', '2026-10-27'::date, '2026-10-27'::date, '09:30:00'::time, '12:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/the-palette-people-at-the-rollo-centre-1895488', true),
  ('Soup Social (PHC)', 'Soup Socials provide delicious and nutritional meals in a casual setting. This is an event within the community to share a meal which fosters social connection and strengthens relationships. Join us and see what interesting conversation you can engage in with your fellow neighbors. Drop-in, all ages. Dates: Tuesdays, 11am-1pm. Location: Summer: Commons (main floor), 675 North Rd. Winter: Fellowship Church, 775 Church St (approx second week of Oct). Cost: FREE or by donation', '2026-10-27'::date, '2026-10-27'::date, '11:00:00'::time, '13:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/soup-social-phc-1884339', true),
