  ('Chair Yoga (Wed 3pm)', 'Gabriola Recreation Society program (26FA-CY3). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-11-04'::date, '2026-11-04'::date, '15:00:00'::time, '16:00:00'::time, false, 'Gabriola Recreation Society space', 'Gabriola Recreation Society space', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('Tech-Help Wednesdays at the Gabriola Library', 'Wednesdays from 3pm-5pm at the Gabriola Library. Let us help you figure out your device issues. Whether it''s your laptop, tablet, eReader, or phone - we will do what we can to reduce your frustrations!Please bring your device, library card, and any passwords you may need. to book your free, 30-minute tech appointment', '2026-11-04'::date, '2026-11-04'::date, '15:00:00'::time, '17:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/tech-help-wednesdays-at-the-gabriola-library-1895902', true),
  ('Youth Group at the Gabriola Fellowship Church', 'Youth group on Wednesdays from 4:30pm to 6:30pm at the Gabriola Fellowship Church', '2026-11-04'::date, '2026-11-04'::date, '16:30:00'::time, '18:30:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/youth-group-at-the-gabriola-fellowship-church-1903080', true),
  ('Games Night at the Gabriola Golf Club', 'Games night at the Gabriola Golf Club on Wednesdays from 6pm-10pm. Poker, cards, board games with expanded menu', '2026-11-04'::date, '2026-11-04'::date, '18:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/games-night-at-the-gabriola-golf-club-1886033', true),
  ('Drop-in Indoor Soccer', 'Gabriola Recreation Society program (26FA-SDI). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-11-04'::date, '2026-11-04'::date, '18:30:00'::time, '20:00:00'::time, false, 'Gabriola Elementary School', 'Gabriola Elementary School', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('Chess at the Rollo Centre', 'Everyone is welcome to drop in for a game of chess on Wednesdays from 7-9pm. We have a regular turnout of roughly 8-10 players (and growing). All ages and levels are welcome. Bring your own board if you like, but we have plenty of the club-style sets available. A $2 activity for Rollo members, $5 drop-in fee for non-members. Play is informal and tea and cookies are provided', '2026-11-04'::date, '2026-11-04'::date, '19:00:00'::time, '21:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/chess-at-the-rollo-centre-1880463', true),
  ('Gabriola Spinners and Weavers Guild', 'We are a group of spinners, weavers, needle felters, wet felters, dyers, knitters, crocheters, finger weavers, and surface designers. We meet at the Rollo Centre on the 1st, 2nd, 3rd, and 5th Thursday of the month year round. The second Thursday meeting offers a three-hour program on a different technique. Guild members demonstrate and sell their creations at Street Art in August and at the Rollo Christmas Craft fair in December. We welcome new members. The GSCA drop-in fee for your first visit is on us. Contact us to be involved', '2026-11-05'::date, '2026-11-05'::date, '09:00:00'::time, '12:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/gabriola-spinners-and-weavers-guild-1896384', true),
  ('Tea Thursdays at the Gabriola Library', 'Enjoy a cup of tea (or spa water on hot days!) all day on Thursdays (10am-7pm), thanks to the Friends of the Gabriola Library', '2026-11-05'::date, '2026-11-05'::date, '10:00:00'::time, '19:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/tea-thursdays-at-the-gabriola-library-1886861', true),
  ('French Conversation Group at the Gabriola Library', 'Come speak French with us on Thursdays at the Gabriola Library from 1pm-2pm. No preparation is necessary. All levels are welcome. We talk about anything and everything. Venez parler français avec nous le jeudi, de 13 h à 14 h. Aucune préparation nécessaire. Tous les niveaux sont bienvenus. On parle de tout et de rien', '2026-11-05'::date, '2026-11-05'::date, '13:00:00'::time, '14:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/french-conversation-group-at-the-gabriola-library-1887144', true),
  ('Gabriola Basketry Group at the Rollo Centre', 'We are an enthusiastic group of artisans who meet every second Thursday at 1:00pm-4:00pm in the small room at the Rollo Centre for an afternoon of basketry. You can check out the Rollo Activity Calendar online or email Marylyn to find out when the next meeting is. The group started meeting and creating in 2002 on Gabriola. Currently we have eight members on Gabriola and about the same number in Nanaimo. Three of our original group are still actively involved in basket making after 23 years!Over the past few years we have jointly facilitated basketry workshops which helps to increase our member numbers. There are no workshops planned at this time. Contact us for information on any future workshops and feel free to drop-in on our regular activity day to check out the group!', '2026-11-05'::date, '2026-11-05'::date, '13:00:00'::time, '16:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/gabriola-basketry-group-at-the-rollo-centre-1896160', true),
  ('Contract Bridge at the Rollo Centre', 'We meet every Thursday afternoon at 1:30pm. There are anywhere from two to five tables (eight to twenty individuals) who play. Lately there have been four tables. A trophy for the highest score overall is given out. Cash prizes are given out for first and second place plus random cash prizes for card sequences. We enjoy a Christmas potluck lunch and party in December', '2026-11-05'::date, '2026-11-05'::date, '13:30:00'::time, '16:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/contract-bridge-at-the-rollo-centre-1885244', true),
  ('Fit for Life After 50', 'Gabriola Recreation Society program (26FA-FFL). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-11-05'::date, '2026-11-05'::date, '13:30:00'::time, '14:30:00'::time, false, 'Gabriola Recreation Society space', 'Gabriola Recreation Society space', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('Ladies Badminton @ The Community Hall', '2pm-4pm. all levels welcome. Join us for fun, casual badminton games open to all skill levels. No registration or partner required, just drop in, meet new people, and enjoy the game!', '2026-11-05'::date, '2026-11-05'::date, '14:00:00'::time, '16:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/ladies-badminton-the-community-hall-1460262', true),
  ('Spanish Conversation Group at the Gabriola Library', 'Drop in and practice your Spanish with the delightful Fernanda (Spanish is her first language), on Thursdays at the Gabriola Library from 3:30pm-4:30pm. Everyone is welcome!', '2026-11-05'::date, '2026-11-05'::date, '15:30:00'::time, '16:30:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/spanish-conversation-group-at-the-gabriola-library-1887223', true),
  ('Drumming at the Gabriola Arts Centre', '6pm - 7:30pm: Simple Rhythms - no experience needed.7:30pm - 9pm: Intermediate African Ensemble SongsEveryone is welcome, no charge, and some hand drums/balafons are provided. Located at the Gabriola Arts Centre', '2026-11-05'::date, '2026-11-05'::date, '18:00:00'::time, '21:00:00'::time, false, 'Gabriola Arts Council', 'Gabriola Arts Council', '476 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/drumming-at-the-gabriola-arts-centre-1884689', true),
  ('Gabriola Garden Club Meeting', 'Meetings are the first Thursday of month at the Rollo Centre. The doors open at 6pm, meeting begins at 6:30pm. Drop-ins welcome, contact us at Membership: $15 for single, $20 for family', '2026-11-05'::date, '2026-11-05'::date, '18:00:00'::time, '20:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/gabriola-garden-club-meeting-1901164', true),
  ('Narcotics Anonymous Meeting at the Gabriola Fellowship Church', 'Narcotics Anonymous meeting at the Gabriola Fellowship Church on Monday and Thursday evenings from 6:00pm - 7:00pm', '2026-11-05'::date, '2026-11-05'::date, '18:00:00'::time, '19:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/narcotics-anonymous-meeting-at-the-gabriola-fellowship-church-1900691', true),
