  ('Line Dancing at the Community Hall', 'Line dancing on Monday evenings from 4pm-6pm at the Gabriola Community Hall', '2026-11-09'::date, '2026-11-09'::date, '16:00:00'::time, '18:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/line-dancing-at-the-community-hall-1887600', true),
  ('Beginner Ukulele Instruction and Singalong', 'Downstairs in the Gabriola Community Hall on Monday evenings from 6pm-8pm. Beginner ukulele: 6-7pm. Sing along and play along: 7-8pm (with a uke or whatever!). Suggested donation = $5', '2026-11-09'::date, '2026-11-09'::date, '18:00:00'::time, '20:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/beginner-ukulele-instruction-and-singalong-1887095', true),
  ('Narcotics Anonymous Meeting at the Gabriola Fellowship Church', 'Narcotics Anonymous meeting at the Gabriola Fellowship Church on Monday and Thursday evenings from 6:00pm - 7:00pm', '2026-11-09'::date, '2026-11-09'::date, '18:00:00'::time, '19:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/narcotics-anonymous-meeting-at-the-gabriola-fellowship-church-1900614', true),
  ('Open Mic Night at the Gabriola Golf Club', 'Local artists from 6pm till 10pm on Mondays at the Gabriola Golf Club, 825 South Rd', '2026-11-09'::date, '2026-11-09'::date, '18:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/open-mic-night-at-the-gabriola-golf-club-1887556', true),
  ('Duplicate Bridge at the Rollo Centre', 'The Duplicate Bridge group meets every Monday evening at 6:30pm for 3 hours of brain gymnastics in a convivial atmosphere. Currently we average 3 tables/evening (12 players), and we are actively recruiting more players. Although we are no longer sanctioned by the ACBL, scores are always tallied and the top pair always enjoys ***FREE PLAY*** for their next session. An activity fee of $4.00 is charged ($2 for Rollo; $2 for cookies). Coffee, tea, and cookies are always served!', '2026-11-09'::date, '2026-11-09'::date, '18:30:00'::time, '21:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/duplicate-bridge-at-the-rollo-centre-1884642', true),
  ('The Palette People at the Rollo Centre', 'Meet to draw, paint, inspire and support each other every Tuesday and Friday from 9:30am to noon, and often into the afternoon at the Rollo Centre. For more information, visit our website: About Gabriola Palette People', '2026-11-10'::date, '2026-11-10'::date, '09:30:00'::time, '12:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/the-palette-people-at-the-rollo-centre-1895492', true),
  ('Soup Social (PHC)', 'Soup Socials provide delicious and nutritional meals in a casual setting. This is an event within the community to share a meal which fosters social connection and strengthens relationships. Join us and see what interesting conversation you can engage in with your fellow neighbors. Drop-in, all ages. Dates: Tuesdays, 11am-1pm. Location: Summer: Commons (main floor), 675 North Rd. Winter: Fellowship Church, 775 Church St (approx second week of Oct). Cost: FREE or by donation', '2026-11-10'::date, '2026-11-10'::date, '11:00:00'::time, '13:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/soup-social-phc-1884341', true),
  ('Yoga for All (Tue 11:30am)', 'Gabriola Recreation Society program (26FA-YA1130). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-11-10'::date, '2026-11-10'::date, '11:30:00'::time, '12:30:00'::time, false, 'Gabriola Recreation Society space', 'Gabriola Recreation Society space', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
