  ('Open Mic Drop-In at the Gabriola Library', 'All writers are welcome to read their work aloud or just sit and listen. Readings are 5-10 minutes. Second and last Friday of each month from 12:30pm-2pm at the Gabriola Library', '2026-11-13'::date, '2026-11-13'::date, '12:30:00'::time, '14:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/open-mic-drop-in-at-the-gabriola-library-1902713', true),
