  ('Beginner Ukulele Instruction and Singalong', 'Downstairs in the Gabriola Community Hall on Monday evenings from 6pm-8pm. Beginner ukulele: 6-7pm. Sing along and play along: 7-8pm (with a uke or whatever!). Suggested donation = $5', '2026-11-16'::date, '2026-11-16'::date, '18:00:00'::time, '20:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/beginner-ukulele-instruction-and-singalong-1887096', false),
  ('Narcotics Anonymous Meeting at the Gabriola Fellowship Church', 'Narcotics Anonymous meeting at the Gabriola Fellowship Church on Monday and Thursday evenings from 6:00pm - 7:00pm', '2026-11-16'::date, '2026-11-16'::date, '18:00:00'::time, '19:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/narcotics-anonymous-meeting-at-the-gabriola-fellowship-church-1900616', true),
  ('Open Mic Night at the Gabriola Golf Club', 'Local artists from 6pm till 10pm on Mondays at the Gabriola Golf Club, 825 South Rd', '2026-11-16'::date, '2026-11-16'::date, '18:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/open-mic-night-at-the-gabriola-golf-club-1887557', true),
  ('Parent and Caregiver Support Group', 'For Parents and caregivers of children of any age who live with disabilities, are neurodivergent, or face other challenges. No diagnosis is needed to participate. You are the experts on your children and your families. Share what has helped, ask questions, or simply listen. Group topics will be shaped by participants and will change every two weeks. A place to connect, share and feel understood-parenting and caregiving ca be a lot', '2026-11-16'::date, '2026-11-16'::date, '18:00:00'::time, '19:30:00'::time, false, 'Gabriola Medical Clinic', 'Gabriola Medical Clinic', '695 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/parent-and-caregiver-support-group-1948198', true),
  ('Duplicate Bridge at the Rollo Centre', 'The Duplicate Bridge group meets every Monday evening at 6:30pm for 3 hours of brain gymnastics in a convivial atmosphere. Currently we average 3 tables/evening (12 players), and we are actively recruiting more players. Although we are no longer sanctioned by the ACBL, scores are always tallied and the top pair always enjoys ***FREE PLAY*** for their next session. An activity fee of $4.00 is charged ($2 for Rollo; $2 for cookies). Coffee, tea, and cookies are always served!', '2026-11-16'::date, '2026-11-16'::date, '18:30:00'::time, '21:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/duplicate-bridge-at-the-rollo-centre-1884643', true),
  ('The Palette People at the Rollo Centre', 'Meet to draw, paint, inspire and support each other every Tuesday and Friday from 9:30am to noon, and often into the afternoon at the Rollo Centre. For more information, visit our website: About Gabriola Palette People', '2026-11-17'::date, '2026-11-17'::date, '09:30:00'::time, '12:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/the-palette-people-at-the-rollo-centre-1895494', true),
  ('Family Caregivers Support Group', 'People for a Healthy Community’s (PHC) Family Caregivers Support Group is a welcoming, peer-facilitated space where caregivers can come together to share experiences, learn from one another, and find comfort in knowing they are not alone. Whether you are new to caregiving or have been supporting someone for years, this group offers a compassionate environment where everyone’s experiences are valued', '2026-11-17'::date, '2026-11-17'::date, '10:00:00'::time, '11:30:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/family-caregivers-support-group-1903156', true),
