  ('Immunization Clinic', 'Listed on the Gabriola Community Hall calendar (a room booking calendar). Times shown are the booking and may include setup. Check with the organizer for event hours.', '2026-11-24'::date, '2026-11-24'::date, NULL::time, NULL::time, true, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Community Hall calendar', 'https://gabriolacommunityhall.com/event-calendar/', false),
  ('AA Gathering at the Community Hall - Women Only', 'AA Group meets downstairs every Wednesday morning at the Gabriola Community Hall from 9am-10am', '2026-11-25'::date, '2026-11-25'::date, '09:00:00'::time, '10:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/aa-gathering-at-the-community-hall-women-only-1895671', false),
  ('Gabriola Quilters at the Rollo Centre', 'We meet the 2nd, 4th, and 5th Wednesdays from 9:30am-4:00pm in the large room at the Rollo Centre. We are a group of individuals who get together to share ideas, work on projects, our own or a group project, and socialize. We love to play with colours and fabric. Members'' skill range from beginner to very experienced. Some members are also fiber artists, some do other forms of needle crafts to be incorporated into their quilts, or while in between projects. Primarily, we work on our own projects. Occasionally we may be involved as a group in projects that benefit the community. The latest example being the Sunflower quilt for PHC.Membership Fees: $20/calendar year - which covers the storage locker rental with some left over to cover other expenses such as our annual show and sale. There is a $2 activity fee paid to the GSCA each time a member attends. Drop-ins are always welcome. The first visit is free and subsequent visits are $5', '2026-11-25'::date, '2026-11-25'::date, '09:30:00'::time, '12:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/gabriola-quilters-at-the-rollo-centre-1896368', true),
  ('Little Songbirds (Infants to age 4)', 'Gabriola Recreation Society program (26FA-LS). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-11-25'::date, '2026-11-25'::date, '10:00:00'::time, '11:00:00'::time, false, 'Gabriola Recreation Society space', 'Gabriola Recreation Society space', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('Shut Up & Write! at the Gabriola Library', 'A 2-hour session of silent writing on Wednesdays at the Gabriola Library. No discussions, just quick introductions then work silently on your writing project. 10am-12pm. Optional discussion period from 12pm-12:30pm', '2026-11-25'::date, '2026-11-25'::date, '10:00:00'::time, '12:30:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/shut-up-write-at-the-gabriola-library-1887001', true),
  ('Mom''s Group at the Gabriola Fellowship Church', 'Mom''s Group meeting every Wednesday at the Gabriola Fellowship Church from 10:30am - 1:30pm. We host a supportive and welcoming space for moms to connect, share experiences, and build lasting friendships. Whether you''re a new mom or seasoned pro, come join us for encouragement, laughter, and real talk about motherhood', '2026-11-25'::date, '2026-11-25'::date, '10:30:00'::time, '13:30:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/mom-s-group-at-the-gabriola-fellowship-church-1901043', true),
  ('Meet for Meditation at the Gabriola Library', 'Meet for meditation on Wednesdays at the Gabriola Library from 1pm-2pm. Art of Living teacher, Susan Murray, will lead you through a wonderfully relaxing session no matter your experience level. No registration required', '2026-11-25'::date, '2026-11-25'::date, '13:00:00'::time, '14:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/meet-for-meditation-at-the-gabriola-library-1887047', true),
