  ('Tech-Help Wednesdays at the Gabriola Library', 'Wednesdays from 3pm-5pm at the Gabriola Library. Let us help you figure out your device issues. Whether it''s your laptop, tablet, eReader, or phone - we will do what we can to reduce your frustrations!Please bring your device, library card, and any passwords you may need. to book your free, 30-minute tech appointment', '2026-11-25'::date, '2026-11-25'::date, '15:00:00'::time, '17:00:00'::time, false, 'Gabriola Library', 'Gabriola Library', '5-575 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/tech-help-wednesdays-at-the-gabriola-library-1895905', true),
  ('Youth Group at the Gabriola Fellowship Church', 'Youth group on Wednesdays from 4:30pm to 6:30pm at the Gabriola Fellowship Church', '2026-11-25'::date, '2026-11-25'::date, '16:30:00'::time, '18:30:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/youth-group-at-the-gabriola-fellowship-church-1903083', true),
  ('Games Night at the Gabriola Golf Club', 'Games night at the Gabriola Golf Club on Wednesdays from 6pm-10pm. Poker, cards, board games with expanded menu', '2026-11-25'::date, '2026-11-25'::date, '18:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/games-night-at-the-gabriola-golf-club-1886036', true),
  ('Drop-in Indoor Soccer', 'Gabriola Recreation Society program (26FA-SDI). Registration, fees and full details on the Gabriola Recreation registration site.', '2026-11-25'::date, '2026-11-25'::date, '18:30:00'::time, '20:00:00'::time, false, 'Gabriola Elementary School', 'Gabriola Elementary School', '680 North Road', 'Gabriola Island', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', 'Gabriola Recreation Society', 'https://app.univerusrec.com/gabriolarecreationpub/courses/', true),
  ('AA Meeting at Gabriola Fellowship Church', 'AA Group meets downstairs weekly at the Gabriola Fellowship Church on the following days and times: Sundays at 7:00 pm Wednesdays at 7:00 pm Fridays at 12:00 pm', '2026-11-25'::date, '2026-11-25'::date, '19:00:00'::time, '20:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/aa-meeting-at-gabriola-fellowship-church-1895744', true),
  ('Chess at the Rollo Centre', 'Everyone is welcome to drop in for a game of chess on Wednesdays from 7-9pm. We have a regular turnout of roughly 8-10 players (and growing). All ages and levels are welcome. Bring your own board if you like, but we have plenty of the club-style sets available. A $2 activity for Rollo members, $5 drop-in fee for non-members. Play is informal and tea and cookies are provided', '2026-11-25'::date, '2026-11-25'::date, '19:00:00'::time, '21:00:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/chess-at-the-rollo-centre-1880466', true),
