  ('Sustainable Gabriola monthly meeting', 'Join us to talk about sustainability issues from a Gabriola perspective. Bring your ideas, find out what’s happening around the community. The meetings are informal, respectful, and open to all', '2026-11-29'::date, '2026-11-29'::date, '15:00:00'::time, '16:30:00'::time, false, 'Gabriola Commons Foundation', 'Gabriola Commons Foundation', '675 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/sustainable-gabriola-monthly-meeting-1920489', true),
  ('AA Meeting at Gabriola Fellowship Church', 'AA Group meets downstairs weekly at the Gabriola Fellowship Church on the following days and times: Sundays at 7:00 pm Wednesdays at 7:00 pm Fridays at 12:00 pm', '2026-11-29'::date, '2026-11-29'::date, '19:00:00'::time, '20:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/aa-meeting-at-gabriola-fellowship-church-1896075', true),
  ('Adult Day Program (PHC)', 'Provides engaging therapeutic activities for individuals experiencing physical, cognitive or social challenges in a safe, supervised environment. Our person-centered programs are developed to offer an opportunity for participants to connect with each other, while also offering respite for caregivers. Dates: Mondays and Fridays, 11:30am-2:30pm. Location: Rollo Seniors Centre, 685 North Rd. Age: 60+ (flexible). Cost: FREE or by donation. Registration required. Participants must complete an Island Health intake assessment. For any questions, please contact seniorsmanager@phcgabriola.org', '2026-11-30'::date, '2026-11-30'::date, '11:30:00'::time, '14:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/adult-day-program-phc-1884589', true),
  ('Ladies Badminton @ The Community Hall', '2pm-4pm. all levels welcome. Join us for fun, casual badminton games open to all skill levels. No registration or partner required, just drop in, meet new people, and enjoy the game!', '2026-11-30'::date, '2026-11-30'::date, '14:00:00'::time, '16:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/ladies-badminton-the-community-hall-1460265', true),
  ('Line Dancing at the Community Hall', 'Line dancing on Monday evenings from 4pm-6pm at the Gabriola Community Hall', '2026-11-30'::date, '2026-11-30'::date, '16:00:00'::time, '18:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/line-dancing-at-the-community-hall-1887603', false),
  ('Beginner Ukulele Instruction and Singalong', 'Downstairs in the Gabriola Community Hall on Monday evenings from 6pm-8pm. Beginner ukulele: 6-7pm. Sing along and play along: 7-8pm (with a uke or whatever!). Suggested donation = $5', '2026-11-30'::date, '2026-11-30'::date, '18:00:00'::time, '20:00:00'::time, false, 'Gabriola Community Hall', 'Gabriola Community Hall', '2200 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/beginner-ukulele-instruction-and-singalong-1887098', false),
  ('Narcotics Anonymous Meeting at the Gabriola Fellowship Church', 'Narcotics Anonymous meeting at the Gabriola Fellowship Church on Monday and Thursday evenings from 6:00pm - 7:00pm', '2026-11-30'::date, '2026-11-30'::date, '18:00:00'::time, '19:00:00'::time, false, 'Gabriola Fellowship Church', 'Gabriola Fellowship Church', '775 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/narcotics-anonymous-meeting-at-the-gabriola-fellowship-church-1900620', true),
  ('Open Mic Night at the Gabriola Golf Club', 'Local artists from 6pm till 10pm on Mondays at the Gabriola Golf Club, 825 South Rd', '2026-11-30'::date, '2026-11-30'::date, '18:00:00'::time, '22:00:00'::time, false, 'Gabriola Golf &amp; Country Club', 'Gabriola Golf &amp; Country Club', '825 South Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/open-mic-night-at-the-gabriola-golf-club-1887559', true),
  ('Parent and Caregiver Support Group', 'For Parents and caregivers of children of any age who live with disabilities, are neurodivergent, or face other challenges. No diagnosis is needed to participate. You are the experts on your children and your families. Share what has helped, ask questions, or simply listen. Group topics will be shaped by participants and will change every two weeks. A place to connect, share and feel understood-parenting and caregiving ca be a lot', '2026-11-30'::date, '2026-11-30'::date, '18:00:00'::time, '19:30:00'::time, false, 'Gabriola Medical Clinic', 'Gabriola Medical Clinic', '695 Church Street', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/parent-and-caregiver-support-group-1948199', true),
  ('Duplicate Bridge at the Rollo Centre', 'The Duplicate Bridge group meets every Monday evening at 6:30pm for 3 hours of brain gymnastics in a convivial atmosphere. Currently we average 3 tables/evening (12 players), and we are actively recruiting more players. Although we are no longer sanctioned by the ACBL, scores are always tallied and the top pair always enjoys ***FREE PLAY*** for their next session. An activity fee of $4.00 is charged ($2 for Rollo; $2 for cookies). Coffee, tea, and cookies are always served!', '2026-11-30'::date, '2026-11-30'::date, '18:30:00'::time, '21:30:00'::time, false, 'Rollo Centre', 'Rollo Centre', '685 North Road', 'Gabriola Island', NULL, NULL, 'Gabriola Events directory', 'https://directory.gabriolaevents.ca/gabriola-events/Details/duplicate-bridge-at-the-rollo-centre-1884645', true)
  ) AS v(title, description, start_date, end_date, start_time, end_time, is_all_day, location,
         venue_name, venue_address, venue_city, organizer_organization, registration_url,
         source_name, source_url, is_approved)
  WHERE NOT EXISTS (
    SELECT 1 FROM events e
    WHERE e.title = v.title AND e.start_date = v.start_date
      AND e.start_time IS NOT DISTINCT FROM v.start_time
      AND e.deleted_at IS NULL
  );

  COMMIT;

  -- Check: counts by source and status
  SELECT source_name, is_approved, count(*) FROM events
  WHERE source_type = 'import_2026_10_10' GROUP BY 1, 2 ORDER BY 1, 2;
  